#!/usr/bin/env bash
# Commit message policy: check every commit reachable from REV (default HEAD).
# Fails on any of:
#   - a Co-authored-by trailer (case-insensitive)
#   - a "generated with" / "generated by" line (case-insensitive)
#   - an author or committer email outside *@users.noreply.github.com
# The committer noreply@github.com is accepted: GitHub sets it on commits it
# creates itself (web edits, merges from the PR page).
#   scripts/check-commit-policy.sh [REV]
#   scripts/check-commit-policy.sh --self-test
set -euo pipefail

MESSAGE_PATTERN='^[[:space:]]*co-authored-by:|generated (with|by)'
EMAIL_OK='^[^@<>[:space:]]+@users\.noreply\.github\.com$'
GITHUB_COMMITTER='noreply@github.com'

# Prints one line per violation in commit $1; prints nothing if the commit is clean.
violations() {
  local raw header email
  raw=$(git cat-file commit "$1")
  # Headers end at the first blank line; the message follows.
  while IFS= read -r header; do
    [ -z "$header" ] && break
    case "$header" in
      author\ *|committer\ *)
        email=$(sed -E 's/^[^<]*<([^>]*)>.*$/\1/' <<<"$header")
        if [[ ! "$email" =~ $EMAIL_OK ]] &&
           ! { [[ "$header" == committer\ * ]] && [ "$email" = "$GITHUB_COMMITTER" ]; }; then
          echo "${header%% *} email not allowed: $email"
        fi
        ;;
    esac
  done <<<"$raw"
  sed '1,/^$/d' <<<"$raw" | grep -iE "$MESSAGE_PATTERN" | sed 's/^/message line not allowed: /' || true
}

check() {
  local rev="${1:-HEAD}" bad=0 out
  for sha in $(git rev-list "$rev"); do
    out=$(violations "$sha")
    if [ -n "$out" ]; then
      echo "commit $sha violates the commit message policy:"
      sed 's/^/  /' <<<"$out"
      bad=1
    fi
  done
  [ "$bad" -eq 0 ] && echo "commit message policy: $(git rev-list --count "$rev") commits pass"
  return "$bad"
}

if [ "${1:-}" = "--self-test" ]; then
  tmp=$(mktemp -d)
  trap 'rm -rf "$tmp"' EXIT
  git -C "$tmp" init -q
  ok_email=1+tester@users.noreply.github.com
  c() { # message [author email] [committer email]
    GIT_AUTHOR_NAME=t GIT_AUTHOR_EMAIL="${2:-$ok_email}" \
    GIT_COMMITTER_NAME=t GIT_COMMITTER_EMAIL="${3:-${2:-$ok_email}}" \
      git -C "$tmp" commit -q --allow-empty -m "$1"
  }
  c "clean commit"
  c $'merged on the web\n\nbody' "$ok_email" "$GITHUB_COMMITTER"
  (cd "$tmp" && check HEAD >/dev/null) || { echo "self-test: clean history flagged"; exit 1; }
  bad_cases=(
    $'x\n\nCo-authored-by: Bot <bot@example.com>'
    $'x\n\nCO-AUTHORED-BY: someone <someone@example.com>'
    $'x\n\n  co-authored-by: Bot <1+bot@users.noreply.github.com>'
    $'x\n\nGenerated with some tool'
    $'x\n\nthis change was generated by a script'
  )
  for msg in "${bad_cases[@]}"; do
    c "$msg"
    if (cd "$tmp" && check HEAD >/dev/null); then echo "self-test: missed message: $msg"; exit 1; fi
    git -C "$tmp" reset -q --hard HEAD~1
  done
  for emails in "dev@example.com $ok_email" "$ok_email dev@example.com" \
                "$GITHUB_COMMITTER $ok_email" "evil@users.noreply.github.com.example.com $ok_email"; do
    read -r a cm <<<"$emails"
    c "x" "$a" "$cm"
    if (cd "$tmp" && check HEAD >/dev/null); then echo "self-test: missed author=$a committer=$cm"; exit 1; fi
    git -C "$tmp" reset -q --hard HEAD~1
  done
  echo "self-test passed"
  exit 0
fi

check "${1:-HEAD}"
